import{_ as a,o as r,c as t,ag as n}from"./chunks/framework.DCKC-kU_.js";const m=JSON.parse('{"title":"Form Proposal: ContainerService","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/container-service.md","filePath":"proposals/container-service.md"}'),i={name:"proposals/container-service.md"};function o(s,e,c,d,l,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="form-proposal-containerservice" tabindex="-1">Form Proposal: ContainerService <a class="header-anchor" href="#form-proposal-containerservice" aria-label="Permalink to &quot;Form Proposal: ContainerService&quot;">​</a></h1><p>Status: active Proposal; intended first v1alpha2 release <code>0.1.0</code>. A local candidate package exists under <code>forms/candidates/v1alpha2/</code>, but no released FormRef or public release identity exists yet.</p><h2 id="need-and-boundary" tabindex="-1">Need and boundary <a class="header-anchor" href="#need-and-boundary" aria-label="Permalink to &quot;Need and boundary&quot;">​</a></h2><p>Takosumi Cloud runs immutable OCI images as long-lived services. The candidate Form describes a digest-pinned image, non-secret configuration, connections, and an <code>http.request@1</code> Interface. Runtime, ports, public routing, probes, scaling, placement, networking, credentials, secret injection, capacity, and price are host decisions.</p><h2 id="substrate-neutrality-review" tabindex="-1">Substrate-neutrality review <a class="header-anchor" href="#substrate-neutrality-review" aria-label="Permalink to &quot;Substrate-neutrality review&quot;">​</a></h2><p>An OCI digest and application configuration have the same meaning for a Kubernetes-based host, a managed container platform, or a local OCI runtime. CPU, memory, replicas, ports, public exposure, and health checks are excluded: they are operating and exposure policy, not the identity of the service workload represented by this Form.</p><h2 id="lifecycle-and-security-risks" tabindex="-1">Lifecycle and security risks <a class="header-anchor" href="#lifecycle-and-security-risks" aria-label="Permalink to &quot;Lifecycle and security risks&quot;">​</a></h2><p>Image changes create reviewed revisions; some networking changes may require replacement. Writable local filesystem is not portable durable state. Delete retires service instances. Registry/runtime credentials and secret env/files never enter portable desired or provider state.</p><h2 id="prior-art-and-gap" tabindex="-1">Prior art and gap <a class="header-anchor" href="#prior-art-and-gap" aria-label="Permalink to &quot;Prior art and gap&quot;">​</a></h2><p>OCCI Application/Component, CIMI Machine/System, TOSCA container runtime and artifacts, Kubernetes Deployment/Service/probes, Crossplane reconciliation, and Terraform ECS/Cloud Run/Container Apps resources are applicable. The gap is a digest-bound service intent smaller than Kubernetes and independent of one managed container product.</p>',10)])])}const h=a(i,[["render",o]]);export{m as __pageData,h as default};
